style.css:
@media screen {
  /* True black background and light gray text for readability */
  html, body, #container, #pageContainer, .content-container, .main-content {
    background-color: #000000 !important;
    color: #e0e0e0 !important;
  }

  /* Panels, modules, and boxes with a dark gray/black mix and red borders */
  header, footer, .watch-video-container, .module, .box, .profile-block, .card, .sidebar {
    background-color: #0b0b0b !important;
    border: 1px solid #ff0000 !important;
    color: #e0e0e0 !important;
  }

  /* Bright red links and titles */
  a, a:visited, .video-title, h1, h2, h3 {
    color: #ff0000 !important;
  }
  
  /* Hovering over links turns them slightly lighter red */
  a:hover {
    color: #ff3333 !important;
  }

  /* Form inputs, textareas, and search bars */
  input, select, textarea, .search-bar {
    background-color: #121212 !important;
    color: #ffffff !important;
    border: 1px solid #ff0000 !important;
  }

  /* Buttons styled in solid red with white text */
  button, .btn, input[type="submit"] {
    background-color: #ff0000 !important;
    color: #ffffff !important;
    border: none !important;
    font-weight: bold !important;
  }
  
  button:hover, .btn:hover {
    background-color: #cc0000 !important;
  }
}
